 {'id':'country','category':'multi-table join','question':'Show completed revenue by customer country, highest first.','sql':"SELECT c.country,round(sum(i.quantity*i.unit_price*(1-i.discount_pct)),2) revenue_aed FROM customers c JOIN orders o USING(customer_id) JOIN order_items i USING(order_id) WHERE o.status='completed' GROUP BY 1 ORDER BY 2 DESC"},
