 {'id':'growth','category':'quarter comparison','question':'Compare completed revenue in Q3 and Q4 2025. Return Q3 revenue, Q4 revenue and percentage growth rounded to two decimals.','sql':"WITH q AS (SELECT quarter(o.order_date) quarter, sum(i.quantity*i.unit_price*(1-i.discount_pct)) revenue FROM orders o JOIN order_items i USING(order_id) WHERE o.status='completed' GROUP BY 1) SELECT round(max(CASE WHEN quarter=3 THEN revenue END),2) q3_revenue, round(max(CASE WHEN quarter=4 THEN revenue END),2) q4_revenue, round(100.0*(max(CASE WHEN quarter=4 THEN revenue END)-max(CASE WHEN quarter=3 THEN revenue END))/nullif(max(CASE WHEN quarter=3 THEN revenue END),0),2) growth_pct FROM q"},
